def solve(xs: list[int]) -> int:
    """Return the length of the longest subsequence of xs whose consecutive
    differences strictly alternate between positive and negative.
    A single element counts as length 1; an empty list counts as 0."""
    if len(xs) <= 1:
        return len(xs)
    up = down = 1
    for i in range(1, len(xs)):
        if xs[i] > xs[i - 1]:
            up = down + 1
        elif xs[i] < xs[i - 1]:
            down = up + 1
    return max(up, down)

def solve(xs: list[int]) -> int:
    # dp[r] = max sum of a subset whose size % 3 == r
    dp = [0, None, None]
    for x in xs:
        ndp = list(dp)
        for r in range(3):
            if dp[r] is not None:
                nr = (r + 1) % 3
                v = dp[r] + x
                if ndp[nr] is None or v > ndp[nr]:
                    ndp[nr] = v
        dp = ndp
    return dp[2] if dp[2] is not None else -1
